import { useState, useEffect, useRef, useCallback, memo } from 'react';
import { useNavigate } from 'react-router-dom';
import { Search, X } from 'lucide-react';
import { searchMulti, img } from '../lib/tmdb';
import type { MediaItem } from '../lib/tmdb';
import MediaCard from '../components/MediaCard';
import { useSettings } from '../contexts/SettingsContext';

function SearchPageInner() {
  const navigate = useNavigate();
  const { settings } = useSettings();
  const [query, setQuery] = useState('');
  const [results, setResults] = useState<MediaItem[]>([]);
  const [loading, setLoading] = useState(false);
  const [hasSearched, setHasSearched] = useState(false);
  const [debounceTimer, setDebounceTimer] = useState<ReturnType<typeof setTimeout> | null>(null);
  const inputRef = useRef<HTMLInputElement>(null);

  // Auto-focus input
  useEffect(() => {
    inputRef.current?.focus();
  }, []);

  // Debounced search
  const handleInputChange = useCallback((value: string) => {
    setQuery(value);
    setHasSearched(false);
    setResults([]);

    if (debounceTimer) clearTimeout(debounceTimer);

    if (value.trim().length < 2) return;

    const timer = setTimeout(async () => {
      setLoading(true);
      try {
        const data = await searchMulti(value.trim(), '1');
        const filtered = (data.results ?? []).filter(
          (r: MediaItem) => r.media_type === 'movie' || r.media_type === 'tv'
        );
        setResults(filtered.slice(0, 50));
        setHasSearched(true);
      } catch {
        setResults([]);
      } finally {
        setLoading(false);
      }
    }, 400);

    setDebounceTimer(timer);
  }, []);

  const handleSearch = (e: React.FormEvent) => {
    e.preventDefault();
    if (debounceTimer) clearTimeout(debounceTimer);
    
    setLoading(true);
    Promise.all([
      searchMulti(query.trim(), '1'),
      searchMulti(query.trim(), '2'),
    ]).then(([r1, r2]) => {
      const allResults = [...(r1.results ?? []), ...(r2.results ?? [])];
      const filtered = allResults.filter(
        (r: MediaItem) => r.media_type === 'movie' || r.media_type === 'tv'
      );
      const unique = Array.from(new Map(filtered.map(item => [item.id, item])).values());
      setResults(unique.slice(0, 100));
      setHasSearched(true);
    }).catch(() => {
      setResults([]);
    }).finally(() => {
      setLoading(false);
    });
  };

  const clearSearch = () => {
    setQuery('');
    setResults([]);
    setHasSearched(false);
    inputRef.current?.focus();
  };

  return (
    <div className="min-h-screen bg-[#0a0a0f] pt-16">
      {/* Search header */}
      <div className="sticky top-16 z-40 bg-[#0a0a0f]/95 backdrop-blur-xl border-b border-white/5">
        <div className="max-w-full lg:max-w-[1600px] xl:max-w-[2000px] 2xl:max-w-[2560px] mx-auto px-4 sm:px-6 py-4">
          <form onSubmit={handleSearch} className="relative">
            <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-white/30" size={20} />
            <input
              ref={inputRef}
              type="text"
              value={query}
              onChange={e => handleInputChange(e.target.value)}
              placeholder="Search for movies, TV shows, people..."
              className="w-full bg-white/5 border border-white/10 text-white placeholder-white/30 rounded-xl pl-12 pr-12 py-3 text-sm focus:outline-none focus:border-white/20 transition-all"
            />
            {query && (
              <button
                type="button"
                onClick={clearSearch}
                className="absolute right-4 top-1/2 -translate-y-1/2 text-white/30 hover:text-white/60 transition-colors"
              >
                <X size={18} />
              </button>
            )}
          </form>
        </div>
      </div>

      {/* Results */}
      <div className="max-w-full lg:max-w-[1600px] xl:max-w-[2000px] 2xl:max-w-[2560px] mx-auto px-4 sm:px-6 py-6">
        {loading ? (
          <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 xl:grid-cols-6 2xl:grid-cols-8 gap-3 sm:gap-4">
            {Array.from({ length: 20 }).map((_, i) => (
              <div key={i} className="animate-pulse">
                <div className="aspect-[2/3] rounded-xl bg-white/5" />
              </div>
            ))}
          </div>
        ) : hasSearched ? (
          <>
            <div className="mb-6 flex items-center justify-between">
              <h1 className="text-xl sm:text-2xl font-bold text-white">
                {query}
              </h1>
              <span className="text-white/40 text-sm">
                {results.length} result{results.length !== 1 ? 's' : ''}
              </span>
            </div>

            {results.length > 0 ? (
              <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 xl:grid-cols-6 2xl:grid-cols-8 gap-3 sm:gap-4">
                {results.map((item, index) => (
                  <MediaCard
                    key={item.id}
                    item={item}
                    mediaType={item.media_type as 'movie' | 'tv'}
                    index={index}
                  />
                ))}
              </div>
            ) : (
              <div className="text-center py-24">
                <Search size={56} className="mx-auto text-white/10 mb-5" />
                <p className="text-white/30 text-lg font-medium">No results found</p>
                <p className="text-white/20 text-sm mt-2">Try searching for a different term</p>
              </div>
            )}
          </>
        ) : (
          <div className="text-center py-32">
            <Search size={64} className="mx-auto text-white/10 mb-6" />
            <p className="text-white/30 text-xl font-medium">Search for content</p>
            <p className="text-white/20 text-sm mt-2">Type at least 2 characters to start searching</p>
          </div>
        )}
      </div>
    </div>
  );
}

export default memo(SearchPageInner);